const INSURANCE_FLOW_TIMEOUT_MS = 8000;

function PageShell({ children }: { children: ReactNode }) {
  return (
    <div className="mx-auto w-full max-w-5xl space-y-6 p-6">
      <a
        href="#insurance-flow-content"
        className="sr-only focus:not-sr-only focus:absolute focus:z-50 focus:rounded focus:bg-white focus:px-3 focus:py-2 focus:text-sm focus:underline"
      >
        Skip to insurance flow content
      </a>
      <main id="insurance-flow-content" className="space-y-4">
        <a
          href="/demo"
          className="inline-block rounded px-3 py-2 text-sm underline focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2"
        >
          Back to all demos
        </a>
        {children}
      </main>
    </div>
  );
}

async function InsuranceFlowContent() {
  try {
    const result = await Promise.race([
      runInsuranceFlow(),
      new Promise<never>((_resolve, reject) => {
        setTimeout(
          () => reject(new Error("Insurance flow timed out")),
          INSURANCE_FLOW_TIMEOUT_MS,
        );
      }),
    ]);

    return (
      <>
        <InsuranceFlowDemo result={result} />
        <InsuranceFlowDeepgramUpload />
      </>
    );
  } catch {
    return (
      <EmptyState
        icon={AlertTriangle}
        title="Insurance flow unavailable"
        description="The local insurance workflow could not run. Check server logs and try again."
      />
    );
  }
}

export default function InsuranceFlowDemoPage() {
  return (
    <PageShell>
      <Suspense
        fallback={
          <p role="status" className="text-sm">
            Loading the insurance flow\u2026
          </p>
        }
      >
        <InsuranceFlowContent />
      </Suspense>
    </PageShell>
  );
}
